package build

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// The glab shim is generated by a `printf '%s\n' 'line' … > …/bin/glab` block
// inside the fetch-glab stage, so its source of truth is a run of single-quoted
// Dockerfile arguments rather than a file on disk. These two markers bracket it.
const (
	glabShimStart = "printf '%s\\n' \\"
	glabShimEnd   = "> /out/usr/local/bin/glab"
)

// extractGlabShim reconstructs the shim script from the embedded Dockerfile.
//
// Needle-matching alone cannot hold this asset: every defect the shim has
// actually shipped was behavioural (failing closed when $HOME was unset,
// running a mutating command twice when glab's own exit code collided with the
// flock timeout sentinel), and each of those was spelled correctly enough to
// satisfy any plausible needle. So the test reassembles the script and runs it.
func extractGlabShim(t *testing.T) string {
	t.Helper()
	body := readAsset(t, "Dockerfile")

	_, rest, found := strings.Cut(body, glabShimStart)
	if !found {
		t.Fatalf("Dockerfile: cannot find the glab shim printf block (%q) — the generator was renamed or removed", glabShimStart)
	}
	block, _, found := strings.Cut(rest, glabShimEnd)
	if !found {
		t.Fatalf("Dockerfile: glab shim printf block has no %q redirect — cannot tell where the script ends", glabShimEnd)
	}

	var lines []string
	for raw := range strings.SplitSeq(block, "\n") {
		line := strings.TrimSpace(raw)
		line = strings.TrimSuffix(line, "\\")
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "'") || !strings.HasSuffix(line, "'") {
			t.Fatalf("Dockerfile: glab shim line is not a single-quoted printf argument: %q", line)
		}
		lines = append(lines, strings.Trim(line, "'"))
	}
	if len(lines) == 0 {
		t.Fatal("Dockerfile: reconstructed glab shim is empty — the block parse is broken, not the shim")
	}
	return strings.Join(lines, "\n") + "\n"
}

// writeShimWithFakeGlab writes the reconstructed shim to a temp dir with REAL
// repointed at a stub that reports its argv and exits with a caller-chosen
// code, so the harness can observe how many times glab ran and with what
// status without needing the real binary.
func writeShimWithFakeGlab(t *testing.T, dir string) (shim string) {
	t.Helper()
	script := extractGlabShim(t)

	const realDecl = "REAL=/usr/local/libexec/glab"
	if !strings.Contains(script, realDecl) {
		t.Fatalf("glab shim: %q is gone — the shim no longer delegates to the libexec binary, or the path moved without the docs and rules following", realDecl)
	}
	fake := filepath.Join(dir, "fake-glab")
	script = strings.Replace(script, realDecl, "REAL="+fake, 1)

	// Appends one line per invocation: the count is what proves "exactly once".
	fakeBody := "#!/bin/sh\necho \"run $*\" >> \"" + filepath.Join(dir, "runs") + "\"\nexit \"${FAKE_GLAB_EXIT:-0}\"\n"
	if err := os.WriteFile(fake, []byte(fakeBody), 0o755); err != nil {
		t.Fatalf("write fake glab: %v", err)
	}
	shim = filepath.Join(dir, "glab")
	if err := os.WriteFile(shim, []byte(script), 0o755); err != nil {
		t.Fatalf("write shim: %v", err)
	}
	return shim
}

func runShim(t *testing.T, dir, shim string, env []string) (runs, exitCode int) {
	t.Helper()
	runsFile := filepath.Join(dir, "runs")
	_ = os.Remove(runsFile)

	cmd := exec.Command("/bin/sh", shim, "some-subcommand")
	cmd.Env = env
	out, err := cmd.CombinedOutput()
	if err != nil {
		var ee *exec.ExitError
		if !asExitError(err, &ee) {
			t.Fatalf("run shim: %v (output %q)", err, out)
		}
		exitCode = ee.ExitCode()
	}

	b, readErr := os.ReadFile(runsFile)
	if readErr != nil {
		return 0, exitCode
	}
	return len(strings.Split(strings.TrimSpace(string(b)), "\n")), exitCode
}

func asExitError(err error, target **exec.ExitError) bool {
	ee, ok := err.(*exec.ExitError)
	if ok {
		*target = ee
	}
	return ok
}

// TestGlabFlockShimRunsGlabExactlyOnce is the regression test for the two
// defects a review found in the first cut of this shim.
//
// The shim exists to serialize glab across containers that share one
// ~/.config/glab-cli mount. That makes it a gate in front of every glab call in
// the image, so the two ways it can betray its caller both matter more than the
// locking itself:
//
//   - Failing closed. The first cut read "$HOME" under `set -u`, so an unset
//     HOME aborted the shim and glab never ran at all — while the docs promised
//     it degraded to running unlocked. A read-only or foreign-UID config dir hit
//     the same wall, because `mkdir -p` succeeds on an existing directory it
//     cannot write into.
//   - Running twice. The first cut used `flock -w 10 -E 99` and treated exit 99
//     as "timed out, retry unlocked". flock passes the child's status through
//     verbatim, so a glab that genuinely exited 99 was indistinguishable from a
//     timeout and the shim re-ran it — repeating the side effects of whatever
//     mutating command the user had asked for.
func TestGlabFlockShimRunsGlabExactlyOnce(t *testing.T) {
	if _, err := os.Stat("/bin/sh"); err != nil {
		t.Skipf("no /bin/sh: %v", err)
	}

	cases := []struct {
		name     string
		home     func(t *testing.T, dir string) string
		exitCode string
		want     int
		skipRoot bool
	}{
		{
			name: "writable home locks and runs",
			home: func(t *testing.T, dir string) string { return dir },
			want: 0,
		},
		{
			// The collision that made the sentinel unsafe.
			name:     "glab exit code 99 is passed through, not retried",
			home:     func(t *testing.T, dir string) string { return dir },
			exitCode: "99",
			want:     99,
		},
		{
			name:     "arbitrary glab exit code is preserved",
			home:     func(t *testing.T, dir string) string { return dir },
			exitCode: "7",
			want:     7,
		},
		{
			// `mkdir -p` returns 0 for an existing directory, so only an actual
			// write probe catches this one.
			name: "unwritable config dir degrades to unlocked",
			// Root ignores the write bits, so under `go test` in the golang
			// image this case would pass no matter what the shim does. Skipped
			// rather than left in as a green that proves nothing.
			skipRoot: true,
			home: func(t *testing.T, dir string) string {
				home := filepath.Join(dir, "ro-home")
				cfg := filepath.Join(home, ".config", "glab-cli")
				if err := os.MkdirAll(cfg, 0o755); err != nil {
					t.Fatalf("mkdir: %v", err)
				}
				if err := os.Chmod(cfg, 0o500); err != nil {
					t.Fatalf("chmod: %v", err)
				}
				t.Cleanup(func() { _ = os.Chmod(cfg, 0o700) })
				return home
			},
			want: 0,
		},
		{
			name: "unusable home path degrades to unlocked",
			home: func(t *testing.T, dir string) string { return "/proc/nonexistent-toolbox-home" },
			want: 0,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if tc.skipRoot && os.Geteuid() == 0 {
				t.Skip("running as root: file permissions are not enforced, so this case cannot fail")
			}
			dir := t.TempDir()
			shim := writeShimWithFakeGlab(t, dir)

			env := []string{"PATH=/usr/bin:/bin", "HOME=" + tc.home(t, dir)}
			if tc.exitCode != "" {
				env = append(env, "FAKE_GLAB_EXIT="+tc.exitCode)
			}

			runs, exitCode := runShim(t, dir, shim, env)
			if runs != 1 {
				t.Errorf("glab ran %d times, want exactly 1 — the shim must neither fail closed nor retry a mutating command", runs)
			}
			if exitCode != tc.want {
				t.Errorf("shim exit code = %d, want %d — glab's own status must reach the caller unchanged", exitCode, tc.want)
			}
		})
	}

	// HOME unset is its own case: it cannot be expressed by setting HOME to a
	// value, and it is what `set -u` turned into a hard failure.
	t.Run("unset HOME degrades to unlocked", func(t *testing.T) {
		dir := t.TempDir()
		shim := writeShimWithFakeGlab(t, dir)

		runs, exitCode := runShim(t, dir, shim, []string{"PATH=/usr/bin:/bin"})
		if runs != 1 {
			t.Errorf("glab ran %d times with HOME unset, want exactly 1 — `set -u` on a bare $HOME is what made this fail closed", runs)
		}
		if exitCode != 0 {
			t.Errorf("shim exit code = %d with HOME unset, want 0", exitCode)
		}
	})
}

// TestGlabFlockShimHoldsLockAcrossExec pins the fd form of the lock.
//
// `flock -w 10 "$LOCK" cmd` would release as soon as flock's own process left,
// and `flock -w 10 9` alone returns non-zero on timeout, which an earlier cut
// turned into a retry. Holding the lock on fd 9 and letting `exec` inherit it
// is what makes the lock cover glab's whole run with a single execution — so
// the descriptor and the exec must stay in the same command group.
func TestGlabFlockShimHoldsLockAcrossExec(t *testing.T) {
	script := extractGlabShim(t)

	if !strings.Contains(script, `9>>"$LOCK"`) {
		t.Error("glab shim: the lock is no longer taken on fd 9 — a lock released before glab execs leaves the config.yml race open for glab's whole run")
	}
	if !strings.Contains(script, `{ flock -w 10 9 || :; exec "$REAL" "$@"; } 9>>"$LOCK"`) {
		t.Error("glab shim: the flock/exec group drifted — `flock -w 10 9 || :` followed by exec inside one fd-9 group is what gives \"lock if possible, run exactly once\"")
	}
	if strings.Contains(script, "-E 99") {
		t.Error("glab shim: the `-E 99` timeout sentinel is back — flock passes the child's status through verbatim, so a glab that exits 99 is indistinguishable from a timeout and the command gets run twice")
	}
	if strings.Contains(script, `"$HOME/`) {
		t.Error("glab shim: a bare $HOME expansion is back — under `set -u` an unset HOME aborts the shim and glab never runs, instead of running unlocked")
	}

	// The guard the credential helper in 60-glab.sh depends on: that helper
	// resolves glab through `command -v`, i.e. back to this shim, so a glab
	// process can invoke glab. flock is not recursive.
	if !strings.Contains(script, `[ -n "${TOOLBOX_GLAB_LOCKED:-}" ] && exec "$REAL" "$@"`) {
		t.Error("glab shim: the re-entrancy guard is gone — init.d/60-glab.sh registers this shim as a git credential helper, so a nested call would wait out the full timeout behind its own parent")
	}
}
